// Assume 'mem_ptr' is page-aligned mapped memory.
void *mem_ptr;
size_t total_bytes = 1048576; // Example: 1MB

// 1. Determine system page size
long page_sz = sysconf(_SC_PAGESIZE);

// 2. Calculate length rounded up to nearest page multiple
size_t len_aligned = (total_bytes + page_sz - 1) & ~(page_sz - 1);

// --- Primary Advice Flags ---

// Optimize for sequential access (e.g., aggressive read-ahead)
madvise(mem_ptr, len_aligned, MADV_SEQUENTIAL);

// Optimize for random access (disable unnecessary read-ahead)
madvise(mem_ptr, len_aligned, MADV_RANDOM);

// Indicate pages are likely needed soon (prefetching hint)
madvise(mem_ptr, len_aligned, MADV_WILLNEED);

// Advice to free resources; subsequent access causes page fault
madvise(mem_ptr, len_aligned, MADV_DONTNEED);

// Clear dirty status and mark pages clean
madvise(mem_ptr, len_aligned, MADV_REMOVE);

// Mark pages as suitable for transparent huge page merging
madvise(mem_ptr, len_aligned, MADV_MERGEABLE);
